$ cat Grow.java
public class Grow {
    static List<Object> keep = new ArrayList<>();
    public static void main(String[] a) throws Exception {
        System.out.println("pid=" + ProcessHandle.current().pid());
        Thread.sleep(3000);                     // 여기서 기준점을 잡는다
        for (int i = 0; i < 60; i++) {          // 스레드 60개
            Thread t = new Thread(() -> { try { Thread.sleep(60000); } catch (Exception e) {} });
            t.setDaemon(true); t.start(); keep.add(t);
        }
        for (int i = 0; i < 120; i++)           // 직접 버퍼 120MB
            keep.add(ByteBuffer.allocateDirect(1<<20));
        Thread.sleep(60000);
    }
}

$ java -Xmx256m -XX:NativeMemoryTracking=summary -cp out Grow &

